// Title: Generate HTML from an Aspose.Cells workbook and extract all hyperlink URLs using C# regular expressions
// Common Searches: how to save an Aspose.Cells workbook as HTML and retrieve link URLs in C# | C# code to parse <a href> values from HTML generated by Aspose.Cells | extract hyperlink URLs from Aspose.Cells HTML output using regex | read and process hyperlinks in HTML file created by Aspose.Cells in .NET | using Aspose.Cells to create HTML and then list all anchor hrefs in C#
// Tags: Aspose.Cells save workbook as HTML | C# regex extract href attributes | hyperlink extraction from generated HTML | parse anchor tags in Aspose.Cells output | regular expression for <a> tags in .NET

using System;
using System.Collections.Generic;
using System.IO;
using System.Text.RegularExpressions;
using Aspose.Cells;

namespace AsposeCellsHtmlLinkExtractor
{
    // The example creates a new Workbook, adds cells with hyperlink values, saves the workbook as an HTML file using Aspose.Cells, reads the generated HTML, applies a case‑insensitive regular expression to locate all <a> tags and capture their href attributes, collects the URLs into a list, and prints each extracted hyperlink to the console.
    class Program
    {
        static void Main(string[] args)
        {
            try
            {
                // 1. Create a new workbook and add some data with hyperlinks
                Workbook workbook = new Workbook();
                Worksheet sheet = workbook.Worksheets[0];
                sheet.Cells["A1"].PutValue("Google");
                // Add hyperlink directly using the overload that accepts a URL string
                sheet.Hyperlinks.Add(0, 0, 1, 1, "https://www.google.com");
                sheet.Cells["A2"].PutValue("Microsoft");
                sheet.Hyperlinks.Add(1, 0, 1, 1, "https://www.microsoft.com");

                // 2. Save the workbook as HTML
                string htmlPath = "output.html";
                workbook.Save(htmlPath, SaveFormat.Html);

                // 3. Verify the HTML file exists before reading
                if (!File.Exists(htmlPath))
                {
                    Console.WriteLine($"Error: The file '{htmlPath}' was not created.");
                    return;
                }

                // 4. Load the generated HTML content
                string htmlContent;
                try
                {
                    htmlContent = File.ReadAllText(htmlPath);
                }
                catch (Exception readEx)
                {
                    Console.WriteLine($"Failed to read HTML file: {readEx.Message}");
                    return;
                }

                // 5. Extract all hyperlink URLs using a regular expression
                List<string> hyperlinkUrls = new List<string>();
                if (!string.IsNullOrEmpty(htmlContent))
                {
                    // Pattern matches <a ... href="url" ...>
                    const string pattern = @"<a[^>]+href\s*=\s*[""']([^""']+)[""']";
                    foreach (Match match in Regex.Matches(htmlContent, pattern, RegexOptions.IgnoreCase))
                    {
                        string href = match.Groups[1].Value;
                        if (!string.IsNullOrEmpty(href))
                        {
                            hyperlinkUrls.Add(href);
                        }
                    }
                }

                // 6. Output the extracted URLs
                Console.WriteLine("Extracted hyperlink URLs:");
                foreach (string url in hyperlinkUrls)
                {
                    Console.WriteLine(url);
                }
            }
            catch (Exception ex)
            {
                // Log any unexpected errors
                Console.WriteLine($"An error occurred: {ex.Message}");
            }
        }
    }
}
